/// search over the generated runs); `None` past the table,
/// `Some("")` when the block has no properties.
pub fn props_of(state_id: u32) -> Option<&'static str> {
    STATE_PROPS
        .binary_search_by(|(lo, hi, _)| {
            if state_id < *lo {
                std::cmp::Ordering::Greater
            } else if state_id >= *hi {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .ok()
        .map(|i| STATE_PROPS[i].2)
}
